@@ -0,0 +1,14 @@
+model:
+  name: hunyuan-video
+  config:
+    load_from_pretrained_path: ${PRETRAINED_PATH:}
+    resolution: ${RESOLUTION:960,544}
+    num_frames: ${NUM_FRAMES:9}
+    config:
+      variant: HYVideo-T/2-cfgdistill
+      guidance: 1000.0
+      in_channels: 16
+      out_channels: 16
+    encoder:
+      llm: ${LLM_ENCODER:}
+      clip: ${CLIP_ENCODER:openai/clip-vit-large-patch14}

@@ -0,0 +1,11 @@
+model:
+  name: mochi-1
+  config:
+    load_from_pretrained_path: ${PRETRAINED_PATH:}
+    resolution: ${RESOLUTION:960,544}
+    num_frames: ${NUM_FRAMES:9}
+    config:
+      attention_mode: flash
+    encoder:
+      t5: ${T5_ENCODER:google/t5-v1_1-xxl}
+      autoencoder: ${VAE_CHECKPOINT:}

@@ -0,0 +1,13 @@
+model:
+  name: sdxl
+  config:
+    load_from_pretrained_path: ${PRETRAINED_PATH:}
+    resolution: ${RESOLUTION:1024}
+    config:
+      trainable_modules: dit
+      snr_gamma: 5.0
+      scale_factor: 0.13025
+    encoder:
+      clip_l: ${CLIP_L_ENCODER:openai/clip-vit-large-patch14}
+      clip_g: ${CLIP_G_ENCODER:laion/CLIP-ViT-bigG-14-laion2B-39B-b160k}
+      autoencoder: ${VAE_CHECKPOINT:}
